'use strict';
(async()=>{const $=s=>document.querySelector(s),bridge=window.RPG_ACCOUNT_BRIDGE,dialog=$('#account-dialog'),body=$('#account-body'),cfg=window.RPG_ACCOUNT_CONFIG;let account=null,googleReady=false,notice='',busy=false;const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function summary(payload){if(!payload)return '<p>아직 저장이 없어요.</p>';let value;try{value=RPG_ENGINE.validate(payload,RPG_DATA);}catch{return '<p>읽을 수 없는 저장입니다.</p>';}const heroes=value.heroes.map((h,i)=>({h,i})).filter(({h})=>h.recruited);return `<b>원정대원 ${heroes.length}명</b><ul>${heroes.map(({h,i})=>`<li>${esc(RPG_DATA.characters[i].name)} · Lv.${h.level} · ${esc(RPG_DATA.characters[i].classes[h.cell].name)} · ${h.stage}스테이지</li>`).join('')||'<li>새 원정대</li>'}</ul>`;}
function render(){if(!account){body.innerHTML='<p>계정 연결을 준비하고 있어요.</p>';return;}const user=account.user;$('#account-open').textContent=user?'☁ 계정 · 저장':'☁ 구글 계정 연결';body.innerHTML=`${notice?`<p class="account-notice" role="status">${esc(notice)}</p>`:''}${user?`<p class="account-email">${esc(user.email||'구글 계정')}으로 로그인했어요.</p><div class="account-compare"><section><h3>이 기기</h3>${summary(bridge.snapshot())}<button data-cloud="upload" ${busy?'disabled':''}>${account.remote?'이 기기 진행을 클라우드에 저장':'현재 원정대를 이 계정에 연결'}</button></section><section><h3>클라우드</h3>${summary(account.remote?.payload)}<small>${account.remote?esc(new Date(account.remote.updated_at).toLocaleString('ko-KR')):'첫 저장을 기다리고 있어요.'}</small><button data-cloud="download" ${busy||!account.remote?'disabled':''}>클라우드 진행으로 이어 하기</button></section></div><p class="account-help">원하는 저장을 선택해 주세요. 저장이 서로 바뀌면 자동으로 덮어쓰지 않고 다시 확인합니다. 불러오기 전 기기 저장은 복구용으로 보관합니다.</p><div class="account-actions"><button data-cloud="refresh" ${busy?'disabled':''}>최신 저장 확인</button><button data-cloud="logout" ${busy?'disabled':''}>로그아웃</button></div>`:`<p>구글 계정에 원정대를 저장하고 모바일·PC에서 이어 하세요.</p><button class="google-login" data-cloud="login" ${busy||!googleReady?'disabled':''}>G　구글로 계속하기</button>${googleReady?'':'<p class="account-help">구글 로그인 연결을 마무리하고 있어요. 기기 저장으로는 계속 플레이할 수 있어요.</p>'}<p class="account-help">로그인만으로 현재 진행을 덮어쓰지 않습니다. 로그인 후 두 저장을 비교해서 선택합니다.</p>`}${bridge.hasBackup()?'<button data-cloud="restore">불러오기 전 기기 저장 복구</button>':''}<a class="textbtn" href="rpg-privacy.html" target="_blank" rel="noopener">개인정보 안내 ↗</a>`;}
async function open(){bridge.pause(true);dialog.showModal();render();if(account?.user){try{await account.refresh();render();}catch(e){notice=e.message;render();}}}
$('#account-open').onclick=open;document.addEventListener('click',e=>{if(e.target.closest('[data-account-open]'))open();});$('#account-close').onclick=()=>dialog.close();dialog.addEventListener('close',()=>bridge.pause(false));
body.onclick=async e=>{const action=e.target.closest('[data-cloud]')?.dataset.cloud;if(!action||busy)return;busy=true;notice='';render();try{if(action==='login')await account.login(new URL('rpg.html',location.href).href);if(action==='upload'){await account.upload(bridge.snapshot());notice='클라우드에 저장했어요.';}if(action==='download'){await account.download();notice='클라우드 진행을 불러왔어요.';}if(action==='restore'){await bridge.restore();notice='이전 기기 저장을 복구했어요. 클라우드 저장은 그대로입니다.';}if(action==='refresh'){await account.refresh();notice='최신 저장을 확인했어요.';}if(action==='logout'){await account.logout();notice='로그아웃했어요. 기기 저장은 유지됩니다.';}}catch(e){notice=e.message||'연결을 확인해 주세요.';}finally{busy=false;render();}};
try{if(!bridge||!cfg||!window.supabase)throw Error('로그인 구성 요소를 불러오지 못했어요.');const client=supabase.createClient(cfg.url,cfg.publishableKey,{auth:{flowType:'pkce',detectSessionInUrl:true,persistSession:true,autoRefreshToken:true,storageKey:'gaetecheon-google-auth'}});account=new RPG_CLOUD_ACCOUNT(client,{validate:p=>RPG_ENGINE.validate(p,RPG_DATA),apply:bridge.apply,checkpoint:bridge.snapshot,change:render,error:e=>{notice=e.message;render();}});await account.init();const r=await fetch(cfg.url+'/auth/v1/settings',{headers:{apikey:cfg.publishableKey}});if(r.ok)googleReady=(await r.json()).external?.google===true;render();if(new URL(location.href).searchParams.has('code')||location.hash.includes('error_description')){if(account.user)open();else{notice='로그인을 완료하지 못했어요. 다시 시도해 주세요.';open();}}}catch(e){notice='계정 연결을 불러오지 못했어요. 기기 저장은 유지됩니다.';if(account)render();else body.textContent=notice;}
})();
